module main

import os
import toml
import sysmodel

// @verifies REQ-INV-007
// The move test: an FB of every shape on every two-core node of system_full moved to each thread on
// the other core in turn — its `thread` line, nothing else — and the system generated by the real
// sysgen (sysmodel's checks, the lowering, ecucheck and loom2v on the node). A move must generate,
// or be refused with one of the reasons below: what a satellite cannot do yet (#424). The list
// shrinks as those close; a move refused for any other reason is a new gap, and fails here.
// FBs of one shape (fb_shape) move alike, so one of each is moved; FB_MOVE_ALL=1 moves every FB.

const move_full_dir = os.join_path(@VMODROOT, 'examples', 'system_full')

// what an FB on a satellite image cannot do yet — each a fragment of its refusal, by the
// requirement it leaves unmet (requirements/placement.toml, docs/fb-placement.md, #424)
const deferred_on_satellite = {
	'REQ-PLACE-010 io point':      'cannot reach a satellite FB'
	'REQ-PLACE-010 io core':       'cross-core io arrives with the target phase'
	'REQ-PLACE-011 eth':           'ends in satellite partition'
}

struct MoveCase {
	node   string
	fb     string
	from   string // its thread now
	thread string // the thread on the other core it moves to
	to_sat bool   // the destination is a satellite image
}

// stage_move copies system_full's configuration into a private tree
fn stage_move(tag string) string {
	dir := sysmodel.private_temp_dir('fb_move_${tag}') or { panic(err) }
	for f in os.ls(move_full_dir) or { panic(err) } {
		if f == 'system.toml' || f.ends_with('.dbc') || f == 'main.v' {
			os.cp(os.join_path(move_full_dir, f), os.join_path(dir, f)) or { panic(err) }
		}
	}
	// each node's config, and the sources an image compiles: its FBs (app/) and entry (main.v)
	for n in os.ls(os.join_path(move_full_dir, 'nodes')) or { panic(err) } {
		src := os.join_path(move_full_dir, 'nodes', n)
		dst := os.join_path(dir, 'nodes', n)
		os.mkdir_all(dst) or { panic(err) }
		for f in ['ecu.toml', 'main.v'] {
			if os.is_file(os.join_path(src, f)) {
				os.cp(os.join_path(src, f), os.join_path(dst, f)) or { panic(err) }
			}
		}
		if os.is_dir(os.join_path(src, 'app')) {
			os.cp_all(os.join_path(src, 'app'), os.join_path(dst, 'app'), true) or { panic(err) }
		}
	}
	return dir
}

// node_signals: a node's own signals (ecu.toml [[signal]]) and the system's (system.toml), by name
fn node_signals(doc toml.Doc) map[string]map[string]toml.Any {
	mut out := map[string]map[string]toml.Any{}
	for s in (doc.value_opt('signal') or { toml.Any([]toml.Any{}) }).array() {
		m := s.as_map()
		out[(m['name'] or { toml.Any('') }).string()] = m
	}
	return out
}

// table_key: a TOML table but its name, keys sorted — what two signals must share to be one kind
fn table_key(m map[string]toml.Any) string {
	mut keys := m.keys().filter(it != 'name')
	keys.sort()
	return keys.map('${it}=${(m[it] or { toml.Any('') }).to_toml()}').join(',')
}

// name_refs: where each string value is named in a node's configuration outside its signal
// declarations and FBs — a DID, a fault, persistence, telemetry — by key path (`did.signal`), so a
// signal, FB or handler something else on the node names is a kind of its own
fn name_refs(doc toml.Doc) map[string][]string {
	mut out := map[string][]string{}
	top := doc.to_any().as_map()
	for k, v in top {
		if k != 'signal' && k != 'fb' {
			collect_refs(v, k, mut out)
		}
	}
	for _, mut paths in out {
		paths.sort()
	}
	return out
}

fn collect_refs(v toml.Any, path string, mut out map[string][]string) {
	match v {
		map[string]toml.Any {
			for k, x in v {
				collect_refs(x, '${path}.${k}', mut out)
			}
		}
		[]toml.Any {
			for x in v {
				collect_refs(x, path, mut out)
			}
		}
		string {
			out[v] << path
		}
		else {}
	}
}

// fb_shape: what decides how a move of an FB generates, without its name or its signals' names —
// its thread, each handler's period, and each signal it reads and writes by kind: a node signal by
// its declaration, a system signal by its fields and direction, and either by the cores of the
// node's other FBs that read or write it (the same core as this FB, or the other) and by what
// else on the node names it (name_refs). Anything else it names (a parameter, an io point) keeps
// its name, so such an FB is a shape of its own; and what names the FB or one of its handlers (a
// fault it raises) is part of its shape too.
fn fb_shape(fm map[string]toml.Any, node string, local map[string]map[string]toml.Any, system map[string]map[string]toml.Any, ends map[string][]string, core_of_fb map[string]i64, refs map[string][]string) string {
	name := (fm['name'] or { toml.Any('') }).string()
	mut out := ['thread=${(fm['thread'] or { toml.Any('') }).string()}']
	for h in (fm['handler'] or { toml.Any([]toml.Any{}) }).array() {
		hm := h.as_map()
		out << 'period=${(hm['period_ms'] or { toml.Any(0) }).i64()}'
		for dir in ['reads', 'writes'] {
			mut kinds := []string{}
			for sig in (hm[dir] or { toml.Any([]toml.Any{}) }).array() {
				sn := sig.string()
				mut cores := []string{}
				for other in ends[sn] {
					if other != name {
						cores << if core_of_fb[other] == core_of_fb[name] { 'same' } else { 'other' }
					}
				}
				cores.sort()
				if sn in local {
					kinds << 'local(${table_key(local[sn])};${cores.join(',')};${refs[sn].join(',')})'
				} else if sn in system {
					m := system[sn]
					way := if (m['producer'] or { toml.Any('') }).string() == node { 'out' } else { 'in' }
					kinds << 'system(${(m['fields'] or { toml.Any('') }).to_toml()};${way};${cores.join(',')};${refs[sn].join(',')})'
				} else {
					kinds << 'named(${sn})'
				}
			}
			kinds.sort()
			out << '${dir}=${kinds.join('|')}'
		}
	}
	// what names the FB itself or one of its handlers (a fault's `from = "Fb.on_10ms"`), by key path
	mut owned := []string{}
	for k, paths in refs {
		if k == name || k.starts_with('${name}.') {
			owned << 'self(${k[name.len..]}:${paths.join(',')})'
		}
	}
	owned.sort()
	out << owned
	return out.join(' ')
}

// move_cases: each FB of each node with a satellite partition, to each thread on another core — of
// FBs of one shape only the first, unless FB_MOVE_ALL is set
fn move_cases() []MoveCase {
	all := os.getenv('FB_MOVE_ALL') != ''
	sys_doc := toml.parse_file(os.join_path(move_full_dir, 'system.toml')) or { panic(err) }
	system := node_signals(sys_doc)
	mut out := []MoveCase{}
	for n in os.ls(os.join_path(move_full_dir, 'nodes')) or { panic(err) } {
		path := os.join_path(move_full_dir, 'nodes', n, 'ecu.toml')
		if !os.is_file(path) {
			continue
		}
		doc := toml.parse_file(path) or { panic(err) }
		mut core_of_thread := map[string]i64{}
		mut sat_thread := map[string]bool{}
		mut threads := []string{}
		for p in (doc.value_opt('partition') or { toml.Any([]toml.Any{}) }).array() {
			pm := p.as_map()
			core := (pm['core'] or { toml.Any(0) }).i64()
			sat := (pm['image'] or { toml.Any('') }).string() != ''
			for t in (pm['thread'] or { toml.Any([]toml.Any{}) }).array() {
				tn := (t.as_map()['name'] or { toml.Any('') }).string()
				core_of_thread[tn] = core
				sat_thread[tn] = sat
				threads << tn
			}
		}
		if !sat_thread.values().any(it) {
			continue
		}
		fbs := (doc.value_opt('fb') or { toml.Any([]toml.Any{}) }).array().map(it.as_map())
		// each signal's FBs (readers and writers), and each FB's core
		mut ends := map[string][]string{}
		mut core_of_fb := map[string]i64{}
		for fm in fbs {
			name := (fm['name'] or { toml.Any('') }).string()
			core_of_fb[name] = core_of_thread[(fm['thread'] or { toml.Any('') }).string()]
			for h in (fm['handler'] or { toml.Any([]toml.Any{}) }).array() {
				hm := h.as_map()
				for dir in ['reads', 'writes'] {
					for sig in (hm[dir] or { toml.Any([]toml.Any{}) }).array() {
						ends[sig.string()] << name
					}
				}
			}
		}
		local := node_signals(doc)
		refs := name_refs(doc)
		mut seen := map[string]bool{}
		for fm in fbs {
			name := (fm['name'] or { toml.Any('') }).string()
			cur := (fm['thread'] or { toml.Any('') }).string()
			shape := fb_shape(fm, n, local, system, ends, core_of_fb, refs)
			if !all && shape in seen {
				continue
			}
			seen[shape] = true
			for t in threads {
				if core_of_thread[t] != core_of_thread[cur] {
					out << MoveCase{n, name, cur, t, sat_thread[t]}
				}
			}
		}
	}
	return out
}

fn move_fb(dir string, c MoveCase) {
	p := os.join_path(dir, 'nodes', c.node, 'ecu.toml')
	text := os.read_file(p) or { panic(err) }
	re := 'name   = "${c.fb}"\nthread = "${c.from}"'
	alt := 'name = "${c.fb}"\nthread = "${c.from}"'
	anchor := if text.contains(re) { re } else { alt }
	assert text.count(anchor) == 1, '${c.node}: no single `name = "${c.fb}"` + `thread` pair to move'
	os.write_file(p, text.replace(anchor, anchor.replace('thread = "${c.from}"', 'thread = "${c.thread}"'))) or {
		panic(err)
	}
}

// loom_tasks: an image's scheduler-table size, from the loom_build.mk its generation wrote
fn loom_tasks(mk string) string {
	text := os.read_file(mk) or { return '1' }
	return text.all_after('loom_max_tasks=').all_before('\n').trim_space()
}

// v_check type-checks one image as its Makefile transpiles it (target flags, its module path)
fn v_check(entry string, tasks string, paths []string) os.Result {
	return os.exec([@VEXE, '-freestanding', '-bare-builtin-dir', 'osal/vrt/bare', '-arch', 'arm32',
		'-target-libc-headers', '-gc', 'none', '-no-bounds-checking', '-enable-globals', '-d',
		'loom_max_tasks=${tasks}', '-path', '@vlib|@vmodules|${@VMODROOT}|${paths.join('|')}', '-check',
		entry])
}

// images_compile generates the moved node as its build does (dbc2cfg, loom2v) and type-checks the
// owner's image and each satellite's against the node's one app module — "generates" is not
// enough, the node must build (REQ-INV-007)
fn images_compile(dir string, node string) string {
	gen := os.join_path(dir, 'gen-${node}.toml')
	doc := toml.parse_file(gen) or { panic(err) }
	dbc := os.join_path(dir, (doc.value_opt('import.dbc') or { toml.Any('') }).string())
	nd := os.join_path(dir, 'nodes', node)
	for sub in ['sig', 'ports', 'gen'] {
		os.mkdir_all(os.join_path(nd, sub)) or { panic(err) }
	}
	dbc2cfg := sysmodel.tool_binary('dbc2cfg') or { panic(err) }
	d := os.exec([dbc2cfg, dbc, os.join_path(nd, 'gen', 'dbc_gen.v')])
	if d.exit_code != 0 {
		return 'dbc2cfg: ${d.output}'
	}
	loom2v := sysmodel.tool_binary('loom2v') or { panic(err) }
	l := os.exec([loom2v, gen, dbc, os.join_path(nd, 'sig', 'signals_gen.v'), os.join_path(nd,
		'ports', 'ports_gen.v'), os.join_path(nd, 'gen', 'loom_gen.v'), os.join_path(nd, 'gen',
		'trace-manifest.csv')])
	if l.exit_code != 0 {
		return 'loom2v: ${l.output}'
	}
	owner_main := if os.is_file(os.join_path(nd, 'main.v')) { os.join_path(nd, 'main.v') } else { os.join_path(dir, 'main.v') }
	o := v_check(owner_main, loom_tasks(os.join_path(nd, 'gen', 'loom_build.mk')), [nd])
	if o.exit_code != 0 {
		return 'owner image: ${o.output}'
	}
	for p in (doc.value_opt('partition') or { toml.Any([]toml.Any{}) }).array() {
		img := (p.as_map()['image'] or { toml.Any('') }).string()
		if img == '' {
			continue
		}
		sd := os.join_path(dir, img)
		sc := v_check(os.join_path(sd, 'main.v'), loom_tasks(os.join_path(sd, 'gen', 'loom_build.mk')),
			[sd, nd])
		if sc.exit_code != 0 {
			return 'satellite image ${img}: ${sc.output}'
		}
	}
	return ''
}

fn run_sysgen(dir string) os.Result {
	bin := sysmodel.tool_binary('sysgen') or { panic(err) }
	return os.exec([bin, os.join_path(dir, 'system.toml')])
}

// refusals: each error line sysgen reports — the system checks, a node's lowering, and the
// ecucheck / loom2v gate on the generated node — never its progress or summary lines
fn refusals(output string) []string {
	return output.split_into_lines().filter(it.starts_with('sysgen: ERROR')
		|| it.starts_with('sysgen: generated ') || it.starts_with('sysgen: node "'))
}

fn test_every_fb_moves_to_the_other_core_or_is_refused_with_a_listed_reason() {
	cases := move_cases()
	assert cases.len >= 2, 'system_full has no two-core node with FBs to move'
	for c in cases {
		dir := stage_move('${c.node}_${c.fb}_${c.thread}')
		defer {
			os.rmdir_all(dir) or {}
		}
		move_fb(dir, c)
		r := run_sysgen(dir)
		what := '${c.node}: moving fb ${c.fb} from thread ${c.from} to ${c.thread}'
		if r.exit_code == 0 {
			why := images_compile(dir, c.node)
			assert why == '', '${what} generates but does not compile:\n${why}'
			continue
		}
		errs := refusals(r.output)
		assert errs.len > 0, '${what} failed with no refusal sysgen names:\n${r.output}'
		// EVERY refusal is one REQ-INV-007 lists; one unlisted beside a listed one is a new gap
		for e in errs {
			mut listed := false
			for _, frag in deferred_on_satellite {
				if c.to_sat && e.contains(frag) {
					listed = true
					break
				}
			}
			assert listed, '${what} was refused for a reason REQ-INV-007 does not list:\n${e}'
		}
	}
}

// the move this example is built around: the CM4's FB moves to the CM7 and the node still generates
fn test_the_co_processor_fb_moves_to_the_owner_core() {
	c := MoveCase{'domain', 'DynamicsModel', 'model', 'fast', false}
	dir := stage_move('dyn_owner')
	defer {
		os.rmdir_all(dir) or {}
	}
	move_fb(dir, c)
	r := run_sysgen(dir)
	assert r.exit_code == 0, r.output
	why := images_compile(dir, 'domain')
	assert why == '', why
}

// an endpoint that IS written stays a check: a move that leaves `from` naming the old partition is
// refused with both names, never generated with the old core's code
fn test_a_stale_from_is_refused_naming_both_partitions() {
	dir := stage_move('stale_from')
	defer {
		os.rmdir_all(dir) or {}
	}
	p := os.join_path(dir, 'nodes', 'domain', 'ecu.toml')
	text := os.read_file(p) or { panic(err) }
	old := 'name   = "TorqueEstimate"\nfields = { nm = "u32" }\n'
	assert text.count(old) == 1
	os.write_file(p, text.replace(old, old + 'from   = "dynamics"\n')) or { panic(err) }
	move_fb(dir, MoveCase{'domain', 'DynamicsModel', 'model', 'fast', false})
	r := run_sysgen(dir)
	assert r.exit_code != 0
	assert r.output.contains('signal "TorqueEstimate" declares from = "dynamics", but fb "DynamicsModel" writes it in partition "powertrain"'), r.output
}

// the node as it is, both images type-checked: each compiles the node's one app module, so each
// must declare every FB's ports, the other core's included
fn test_the_unmoved_node_compiles_on_both_cores() {
	dir := stage_move('unmoved')
	defer {
		os.rmdir_all(dir) or {}
	}
	r := run_sysgen(dir)
	assert r.exit_code == 0, r.output
	why := images_compile(dir, 'domain')
	assert why == '', why
}
